<script setup lang="ts">
import {computed,reactive,ref} from 'vue';
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app';
import StudioAdminShell from '../../components/StudioAdminShell.vue';
import StudioCustomerIdentity from '../../components/StudioCustomerIdentity.vue';
import {useStudioNative} from '../../utils/studio-native';
import {adminCall,adminError,confirmAdmin,requestKey,today} from '../../utils/studio-admin';
import copy from '../../../../05_studio/src/content/workbench.json';
import wallet from '../../../../05_studio/src/content/wallet.json';
import {hoursNumber,minutesFromHours} from '../../../../05_studio/src/time-units';
import {centsFromInput} from '../../../../05_studio/src/business-model';
const {language,keyboardOpen,shellStyle,say,changeLanguage}=useStudioNative();
const busy=ref(false),saving=ref(false),error=ref(''),data=ref<any>(),note=ref(''),editing=ref(false),page=ref(1),bill=ref(''),noPromotion=ref(false);
let ident='',alive=true,key=requestKey();
const attemptPayload=ref<any>(null);
const form=reactive({kind:'topup',hours:'',points:'',reason:'',effective_date:today(),reservation_id:'',redemption_use:'visit'});
const kinds=['topup','gift','usage','redeem','adjustment'];const labels=computed(()=>kinds.map(k=>say((wallet as Record<string,string[]>)[k])));
const kindLabel=(key:string)=>say((wallet as Record<string,string[]>)[key]||wallet.adjustment);
async function load(more=false){if(busy.value)return;busy.value=true;error.value='';if(!more)page.value=1;try{const result=await adminCall<any>('/manage/members/'+encodeURIComponent(ident),{page:page.value});if(alive){if(more&&data.value)result.entries=[...data.value.entries,...result.entries];data.value=result;note.value=result.account.staff_note||'';}}catch(e){error.value=adminError(e,say);}finally{busy.value=false;}}
async function saveNote(){if(!data.value||saving.value)return;saving.value=true;error.value='';try{data.value=await adminCall('/manage/members/'+encodeURIComponent(ident),{version:data.value.account.version,staff_note:note.value},'PATCH');uni.showToast({title:say(copy.saved),icon:'none'});}catch(e){error.value=adminError(e,say);}finally{saving.value=false;}}
async function save(){if(!data.value||saving.value)return;let payload=attemptPayload.value;
 if(!payload){const minutes=form.kind==='redeem'?0:minutesFromHours(form.hours.trim()||'0'),points=form.points.trim()?Number(form.points):0;
 if(minutes===null||Math.abs(minutes)>1000000||(form.kind!=='adjustment'&&minutes<0)){error.value=say(wallet.invalid_hours);return;}
 if(!Number.isInteger(points)||!form.reason.trim()){error.value=say(copy.invalid_number);return;}
 payload={version:data.value.account.version,kind:form.kind,minutes_delta:form.kind==='usage'?-Math.abs(minutes):minutes,points_delta:form.kind==='redeem'?-Math.abs(points)*100:points,note:form.reason,effective_date:form.effective_date,reservation_id:form.reservation_id};
 if(form.kind==='redeem'){const amount=centsFromInput(bill.value);if(amount===null){error.value=say(copy.invalid_number);return;}payload={...payload,minutes_delta:0,bill_cents:amount,redemption_use:form.redemption_use,no_promotion:noPromotion.value};}
 if(!await confirmAdmin(say(copy.account_confirm),`${say(wallet.time_hours)}: ${hoursNumber(payload.minutes_delta)} · ${say(wallet.points_amount)}: ${payload.points_delta}`,say(copy.confirm),say(copy.cancel)))return;
 attemptPayload.value=payload;}
 saving.value=true;error.value='';try{data.value=await adminCall('/manage/members/'+encodeURIComponent(ident)+'/transactions',payload,'POST',{'Idempotency-Key':key});attemptPayload.value=null;key=requestKey();editing.value=false;Object.assign(form,{hours:'',points:'',reason:''});uni.showToast({title:say(wallet.saved),icon:'none'});}
 catch(e){error.value=adminError(e,say);if((e as any).status>=400&&(e as any).status<500){attemptPayload.value=null;key=requestKey();}}
 finally{saving.value=false;}}
onLoad(q=>{ident=typeof q?.id==='string'?q.id:'';form.reservation_id=typeof q?.reservation==='string'?q.reservation:'';});onShow(()=>{if(!editing.value)void load();});onUnload(()=>{alive=false;});
</script>
<template><StudioAdminShell :title="data?.account.name||say(copy.profile)" back :language="language" :shell-style="shellStyle" :keyboard-open="keyboardOpen" :busy="busy" :error="error" @refresh="load()" @language="changeLanguage"><template v-if="data">
 <view class="admin-card admin-stack"><StudioCustomerIdentity :customer="data.account" :language="language"/><view class="admin-pair"><view class="admin-stack"><text class="admin-label">{{say(wallet.remaining_time)}}</text><text>{{say(copy.hours).replace('{count}',hoursNumber(data.account.minutes))}}</text></view><view class="admin-stack"><text class="admin-label">{{say(wallet.remaining_points)}}</text><text>{{data.account.points}}</text></view></view></view>
 <view class="admin-card admin-stack"><text class="admin-label">{{say(wallet.private_note)}}</text><textarea v-model="note" class="admin-textarea" maxlength="1500" :adjust-position="false"/><button class="admin-secondary" :disabled="saving" @tap="saveNote">{{say(wallet.save_note)}}</button></view>
 <button v-if="!editing" class="admin-primary" @tap="editing=true">{{say(wallet.transaction)}}</button>
 <view v-if="editing" class="admin-card"><view class="admin-field"><text class="admin-label">{{say(wallet.kind)}}</text><picker :disabled="!!attemptPayload" :range="labels" :value="kinds.indexOf(form.kind)" @change="form.kind=kinds[Number($event.detail.value)];form.hours='';form.points=''"><view class="admin-input">{{labels[kinds.indexOf(form.kind)]}}</view></picker></view>
 <view v-if="form.kind!=='redeem'" class="admin-field"><text class="admin-label">{{say(wallet.time_hours)}}</text><input v-model="form.hours" class="admin-input" :type="form.kind==='adjustment'?'text':'digit'" :disabled="!!attemptPayload"/></view><view v-if="['gift','redeem','adjustment'].includes(form.kind)" class="admin-field"><text class="admin-label">{{say(form.kind==='redeem'?wallet.redeem_cad:wallet.points_amount)}}</text><input v-model="form.points" class="admin-input" type="text" :disabled="!!attemptPayload"/></view>
 <text v-if="form.kind==='usage'" class="admin-muted">{{say(wallet.debit_help)}}</text><text v-if="form.kind==='adjustment'" class="admin-muted">{{say(wallet.adjust_help)}}</text>
 <template v-if="form.kind==='redeem'"><view class="admin-field"><text class="admin-label">{{say(wallet.bill)}}</text><input v-model="bill" class="admin-input" type="digit" :disabled="!!attemptPayload"/></view><view class="admin-field"><picker :disabled="!!attemptPayload" :range="[say(wallet.redeem_visit),say(wallet.redeem_shop)]" :value="form.redemption_use==='visit'?0:1" @change="form.redemption_use=Number($event.detail.value)===0?'visit':'shop'"><view class="admin-input">{{say(form.redemption_use==='visit'?wallet.redeem_visit:wallet.redeem_shop)}}</view></picker></view><checkbox-group @change="noPromotion=$event.detail.value.includes('confirmed')"><label class="admin-muted"><checkbox value="confirmed" :checked="noPromotion" :disabled="!!attemptPayload"/>{{say(wallet.no_promotion)}}</label></checkbox-group></template>
 <view class="admin-field"><text class="admin-label">{{say(wallet.date)}}</text><picker mode="date" :value="form.effective_date" :end="today()" :disabled="!!attemptPayload" @change="form.effective_date=$event.detail.value"><view class="admin-input">{{form.effective_date}}</view></picker></view><view class="admin-field"><text class="admin-label">{{say(wallet.reason)}}</text><textarea v-model="form.reason" class="admin-textarea" maxlength="600" :disabled="!!attemptPayload" :adjust-position="false"/></view><view class="admin-field"><text class="admin-label">{{say(wallet.reservation)}}</text><input v-model="form.reservation_id" class="admin-input" maxlength="64" :disabled="!!attemptPayload"/></view><button class="admin-primary" :disabled="saving" @tap="save">{{say(saving?wallet.saving:attemptPayload?wallet.retry:wallet.save)}}</button><button v-if="!attemptPayload" class="admin-secondary native-member-cancel" @tap="editing=false">{{say(wallet.cancel)}}</button></view>
 <view class="admin-row native-member-ledger"><text class="admin-name">{{say(copy.ledger)}}</text><text class="admin-muted">{{data.total}}</text></view><view v-for="entry in data.entries" :key="entry.id" class="admin-card admin-stack"><view class="admin-row"><text>{{kindLabel(entry.kind)}}</text><text class="admin-muted">{{entry.effective_date}}</text></view><text v-if="entry.minutes_delta">{{entry.minutes_delta>0?'+':''}}{{hoursNumber(entry.minutes_delta)}} · {{say(wallet.time_hours)}}</text><text v-if="entry.points_delta">{{entry.points_delta>0?'+':''}}{{entry.points_delta}} · {{say(wallet.points_amount)}}</text><text class="admin-muted">{{entry.note}}</text></view><button v-if="data.entries.length<data.total" class="admin-secondary" :disabled="busy" @tap="page++;load(true)">{{say(copy.more)}}</button></template></StudioAdminShell></template>
<style scoped>.native-member-ledger{margin:22px 0 12px}.native-member-cancel{margin-top:10px}</style>
